def count_monochromatic_triples(n, coloring):
    """
    Calculates the total number of monochromatic triples (x, y, z) 
    from {1, ..., n} such that x + y + z is divisible by n, 
    given a coloring function.

    Coloring: 0 for Red, 1 for Blue.
    """

    total_count = 0

    # Iterate over all triples (x, y, z)
    for x in range(1, n + 1):
        for y in range(1, n + 1):
            for z in range(1, n + 1):

                # Check if they have the same color
                if coloring(x) == coloring(y) and coloring(y) == coloring(z):

                    # Check if the sum is divisible by n
                    if (x + y + z) % n == 0:
                        total_count += 1

    return total_count

# --- Define Colorings ---

# Coloring 1: Parity based
# 0 = Red (Odd), 1 = Blue (Even)
def coloring_parity(i):
    return 0 if i % 2 != 0 else 1

# Coloring 2: Split based on magnitude (up to n/2)
# 0 = Red (i <= n/2), 1 = Blue (i > n/2)
def coloring_split(i, n):
    return 0 if i <= n / 2 else 1

# --- Exploration ---

N_LIMIT = 100 # Increased limit based on theoretical estimation
results = {}

print(f"--- Starting Computational Exploration for n = 1 to {N_LIMIT} ---")

for n in range(1, N_LIMIT + 1):

    # Test Coloring 1 (Parity)
    # Note: coloring_parity is independent of n, but the set S depends on n.
    count1 = count_monochromatic_triples(n, coloring_parity)

    # Test Coloring 2 (Split) - Must pass n to the coloring function
    count2 = count_monochromatic_triples(n, lambda i: coloring_split(i, n))

    results[n] = {
        "C1_Parity": count1,
        "C2_Split": count2
    }

    # Outputting results only for selected points to avoid excessive log spam
    if n % 10 == 0 or n <= 15 or n > N_LIMIT - 5:
        print(f"\n--- Results for n = {n} ---")
        print(f"Coloring 1 (Parity): Count = {count1}")
        print(f"Coloring 2 (Split): Count = {count2}")

# Check for results approaching 2007
print("\n=========================================")
print("Summary of Results (Target = 2007):")
approaching_n = []
TARGET = 2007
for n, counts in results.items():
    c1 = counts["C1_Parity"]
    c2 = counts["C2_Split"]

    if abs(c1 - TARGET) < 100 or abs(c2 - TARGET) < 100: 
        approaching_n.append((n, c1, c2))

if approaching_n:
    print("The following values of n yield counts close to 2007:")
    for n, c1, c2 in approaching_n:
        print(f"n={n}: C1={c1}, C2={c2}")
else:
    print("No values of n <= 100 yield counts close to 2007 with these colorings.")
print("=========================================")

